extern printf(fmt: string, ...);

frame main() ret int {
    # Lambda with parameters and return type
    local add: Lambda<int>(int, int) = |a: int, b: int| ret int {
        return a + b;
    };

    printf("5 + 3 = %d\n", add(5, 3));

    # Lambda with no parameters
    local greet: Lambda<void>() = || {
        printf("Hello from lambda!\n");
    };
    greet();

    # Lambda with single parameter
    local square: Lambda<int>(int) = |x: int| ret int {
        return x * x;
    };
    printf("5 squared = %d\n", square(5));

    # Lambda returning bool
    local isPositive: Lambda<bool>(int) = |n: int| ret bool {
        return n > 0;
    };
    printf("Is 10 positive? %d\n", isPositive(10));
    printf("Is -5 positive? %d\n", isPositive(-5));

    return 0;
}

extern printf(fmt: string, ...);

frame main() ret int {
    # Variable in outer scope
    local factor: int = 10;

    # Lambda captures 'factor' by value at creation time
    local multiply: Lambda<int>(int) = |x: int| ret int {
        return x * factor;  # Uses captured 'factor' value
    };

    printf("factor = %d\n", factor);
    printf("5 * factor = %d\n", multiply(5));
    printf("3 * factor = %d\n", multiply(3));

    # Demonstrate by-value capture semantics
    local value: int = 100;
    local showValue: Lambda<void>() = || {
        printf("Captured value = %d\n", value);
    };

    # Changing value after capture doesn't affect lambda
    value = 999;
    printf("\nvalue in main = %d\n", value);
    showValue();  # Still shows 100 (captured at creation)

    return 0;
}

