# Higher-order function: takes a function as argument
frame apply(op: Lambda<int>(int, int), a: int, b: int) ret int {
    return op(a, b);
}

# Process array with a transform function
frame mapArray(arr: *int, len: int, transform: Lambda<int>(int)) {
    loop (local i: int = 0; i < len; i = i + 1) {
        *(arr + i) = transform(*(arr + i));
    }
}

frame printArray(arr: *int, len: int) {
    loop (local i: int = 0; i < len; i = i + 1) {
        printf("%d ", *(arr + i));
    }
    printf("\n");
}

frame main() ret int {
    # Pass lambdas to apply()
    local sum: int = apply(|a: int, b: int| ret int { return a + b; }, 10, 5);
    local diff: int = apply(|a: int, b: int| ret int { return a - b; }, 10, 5);
    local prod: int = apply(|a: int, b: int| ret int { return a * b; }, 10, 5);

    printf("10 + 5 = %d\n", sum);
    printf("10 - 5 = %d\n", diff);
    printf("10 * 5 = %d\n", prod);

    # Transform array
    local data: int[5] = [1, 2, 3, 4, 5];

    printf("\nOriginal: ");
    printArray(&data[0], 5);

    mapArray(&data[0], 5, |x: int| ret int { return x * 2; });
    printf("Doubled: ");
    printArray(&data[0], 5);

    mapArray(&data[0], 5, |x: int| ret int { return x + 10; });
    printf("Plus 10: ");
    printArray(&data[0], 5);

    return 0;
}

