# Regular function
frame regularAdd(a: int, b: int) ret int {
    return a + b;
}

# Function that takes a raw function pointer (Func)
frame useFuncPointer(f: Func<int>(int, int), a: int, b: int) ret int {
    return f(a, b);
}

# Function that takes a lambda (can capture state)
frame useLambda(f: Lambda<int>(int, int), a: int, b: int) ret int {
    return f(a, b);
}

frame main() ret int {
    # Func: raw function pointer, no captures
    local funcPtr: Func<int>(int, int) = regularAdd;
    printf("Func pointer: %d\n", funcPtr(5, 3));

    # Lambda: can capture variables
    local offset: int = 100;
    local lambdaWithCapture: Lambda<int>(int, int) = |a: int, b: int| ret int {
        return a + b + offset;  # Captures offset
    };
    printf("Lambda with capture: %d\n", lambdaWithCapture(5, 3));

    # Lambda without captures can be used where Lambda expected
    local simpleLambda: Lambda<int>(int, int) = |a: int, b: int| ret int {
        return a + b;
    };
    printf("Simple lambda: %d\n", useLambda(simpleLambda, 5, 3));

    # Regular function can be used as Func
    printf("Regular func via Func: %d\n", useFuncPointer(regularAdd, 5, 3));

    return 0;
}

