extern printf(fmt: string, ...);

frame reduce(arr: *int, len: int, init: int, op: Lambda<int>(int, int)) ret int {
    local acc: int = init;
    loop (local i: int = 0; i < len; i = i + 1) {
        acc = op(acc, *(arr + i));
    }
    return acc;
}

frame main() ret int {
    local nums: int[5] = [1, 2, 3, 4, 5];

    local sum: int = reduce(&nums[0], 5, 0, |a: int, b: int| ret int { return a + b; });
    printf("Sum: %d\n", sum);

    local product: int = reduce(&nums[0], 5, 1, |a: int, b: int| ret int { return a * b; });
    printf("Product: %d\n", product);

    local max: int = reduce(&nums[0], 5, nums[0], |a: int, b: int| ret int {
        if (a > b) { return a; }
        return b;
    });
    printf("Max: %d\n", max);

    return 0;
}
